Specification:
{"summary": "Fetch details of a specific portfolio", "description": "Retrieves detailed information about a specific investment portfolio by its ID.", "parameters": [{"name": "portfolioId", "in": "path", "required": true, "description": "Unique ID of the portfolio", "schema": {"type": "string"}}], "responses": {"200": {"description": "Portfolio details retrieved successfully", "content": {"application/json": {"schema": {"$ref": "#/components/schemas/PortfolioDetails"}}}}}}

