Specification:
{"summary": "Access market insights and trends", "description": "Retrieves market insights and recent trends from the real estate sector.", "responses": {"200": {"description": "Market insights retrieved successfully", "content": {"application/json": {"schema": {"$ref": "#/components/schemas/MarketInsights"}}}}}}

Endpoint: PUT /investment-portfolio/{portfolioId}
Specification:
{"summary": "Update portfolio details", "description": "Updates existing information for the specified real estate investment portfolio.", "parameters": [{"name": "portfolioId", "in": "path", "required": true, "description": "Unique ID of the portfolio", "schema": {"type": "string"}}], "requestBody": {"required": true, "content": {"application/json": {"schema": {"$ref": "#/components/schemas/UpdatedPortfolio"}}}}, "responses": {"200": {"description": "Portfolio updated successfully", "content": {"application/json": {"schema": {"$ref": "#/components/schemas/PortfolioDetails"}}}}}}

