Specification:
{"summary": "Create a new portfolio entry", "description": "Creates a new real estate investment portfolio for the investor.", "requestBody": {"required": true, "content": {"application/json": {"schema": {"$ref": "#/components/schemas/NewPortfolio"}}}}, "responses": {"201": {"description": "Portfolio created successfully", "content": {"application/json": {"schema": {"$ref": "#/components/schemas/PortfolioSummary"}}}}}}

Endpoint: GET /performance-reports/{portfolioId}
Specification:
{"summary": "Generate performance reports", "description": "Generates and downloads detailed performance reports for a specific investment portfolio.", "parameters": [{"name": "portfolioId", "in": "path", "required": true, "description": "Unique ID of the portfolio", "schema": {"type": "string"}}], "responses": {"200": {"description": "Performance report generated successfully", "content": {"application/pdf": {"schema": {"type": "string", "format": "binary"}}}}}}
